def simulate_game(n):
    S = set()
    A = set()  # Alice's choices
    B = set()  # Bob's choices
    is_alice_turn = True

    def get_available_moves(player_set, all_chosen):
        """Finds all valid moves for the current player."""
        valid_moves = []
        if not player_set:
            # If the player has no choices yet, any unused number is valid (since it can't be consecutive to anything they chose)
            for i in range(1, n + 1):
                if i not in all_chosen:
                    valid_moves.append(i)
            return valid_moves

        # Check for numbers not yet chosen
        for i in range(1, n + 1):
            if i not in all_chosen:
                # Check condition (ii): cannot be consecutive to any of those the player has already chosen
                is_consecutive_to_own_set = False
                for chosen_num in player_set:
                    if abs(i - chosen_num) == 1:
                        is_consecutive_to_own_set = True
                        break

                if not is_consecutive_to_own_set:
                    valid_moves.append(i)

        # We assume a specific strategy: pick the smallest valid move
        return sorted(valid_moves)

    while True:
        if is_alice_turn:
            player_set = A
            current_player_name = "Alice"
        else:
            player_set = B
            current_player_name = "Bob"

        # Find moves (returns a sorted list)
        possible_moves = get_available_moves(player_set, S)

        if not possible_moves:
            # Player cannot move
            if len(S) == n:
                return "Draw"
            else:
                # Player loses, game does not end in a draw (it ends by loss)
                return f"{current_player_name} loses"

        # Player makes the move (smallest valid move)
        move = possible_moves[0]
        S.add(move)

        if is_alice_turn:
            A.add(move)
        else:
            B.add(move)

        is_alice_turn = not is_alice_turn

        # Check for draw condition immediately after a move
        if len(S) == n:
            return "Draw"


# Simulation for n=1 to n=15
draw_n_values = []
results = {}

for n in range(1, 16):
    result = simulate_game(n)
    results[n] = result
    if result == "Draw":
        draw_n_values.append(n)

print("--- Results ---")
print(f"N values resulting in a Draw: {draw_n_values}")
print("Full results dictionary:", results)

